using System;using System.Linq;using UnityEngine;using AntColony.Units;
public static class Native1112UV{public static string Run(){var lib=Resources.Load<MeshyNativeLibrary>("MeshyNative/Library");var mesh=lib.characters[1].GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh;var uv=mesh.uv;Debug.Log("Native UV="+uv.Length+" first="+string.Join(",",uv.Take(5))+" old="+string.Join(",",Resources.Load<GameObject>("Kemono/Kemono_Character").GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh.uv.Take(5)));var set=uv.Select(v=>((int)Math.Round(v.x*100000),(int)Math.Round(v.y*100000))).ToHashSet();return "native="+uv.Length+" "+string.Join(",",uv.Take(5))+" old="+string.Join(",",Resources.Load<GameObject>("Kemono/Kemono_Character").GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh.uv.Take(5))+"\n"+string.Join("\n",Resources.Load<GameObject>("Kemono/Kemono_Character").GetComponentsInChildren<SkinnedMeshRenderer>().Select(s=>s.name+" "+s.sharedMesh.uv.Count(v=>set.Contains(((int)Math.Round(v.x*100000),(int)Math.Round(v.y*100000))))+"/"+s.sharedMesh.vertexCount));}}
